def is_samepatterns(words, patterns):
    """
    Checks whether the words follow the sequence given in the patterns array.

    Args:
        words: A list of strings representing the words.
        patterns: A list of strings representing the patterns.

    Returns:
        bool: True if the words follow the sequence, False otherwise.
    """
    if len(words) != len(patterns):
        return False

    word_to_pattern = {}
    pattern_to_word = {}

    for word, pattern in zip(words, patterns):
        # Check consistency for the word -> pattern mapping
        if word in word_to_pattern:
            if word_to_pattern[word] != pattern:
                return False
        else:
            word_to_pattern[word] = pattern

        # Check consistency for the pattern -> word mapping
        if pattern in pattern_to_word:
            if pattern_to_word[pattern] != word:
                return False
        else:
            pattern_to_word[pattern] = word

    return True
