def start_withp(word_list):
    """
    Returns two words from a list of words starting with letter 'p'.
    """
    p_words = []
    for item in word_list:
        # Split the item by spaces to get individual words
        words = item.split()
        for word in words:
            # Check if the word starts with 'p' (case-sensitive as per example)
            if word.startswith('p'):
                p_words.append(word)

    # Return the first two found words, or fewer if less than two are available
    if len(p_words) >= 2:
        return (p_words[0], p_words[1])
    elif len(p_words) == 1:
        return (p_words[0], None)  # Or handle as per specific requirement for missing second word
    else:
        return (None, None)

